package msm_test.block;

import com.mojang.serialization.Codec;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.fabricmc.fabric.api.attachment.v1.AttachmentRegistry;
import net.fabricmc.fabric.api.attachment.v1.AttachmentType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.world.Container;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.ContainerUser;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import msm_test.BlockWaxing;

/**
 * Per-player storage (ADR 0104 D5 and its amendment after B503, X9): a chest with {@code per_player} shows each player
 * their own contents, kept in the persistent Fabric attachment {@code <mod id>:player_stores} on the player, one store
 * per block family ({@link #key}), as vanilla's ender chest keeps one store for every ender chest (limit N7). The
 * attachment is copied on death (a respawned player is a new object) and is the same object after a dimension change; it
 * is saved with the player under {@code fabric:attachments}. Not synced to clients: the menu sends the contents.
 *
 * <p>The block keeps its {@link StorageBlockEntity} for the {@code open} property, the sounds and {@code on_open} and
 * {@code on_close} (its own slots stay empty); hoppers and comparators do not reach the store, as vanilla's ender chest.
 */
public final class PlayerStores {
    private static final String MOD_ID = "msm_test";
    private static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);
    public static final Identifier ID = Identifier.fromNamespaceAndPath(MOD_ID, "player_stores");

    /** Store key (a block id) to the store's slots, empty slots included. */
    public static final AttachmentType<Map<String, List<ItemStack>>> TYPE = AttachmentRegistry.create(ID,
            builder -> builder.persistent(Codec.unboundedMap(Codec.STRING, ItemStack.OPTIONAL_CODEC.listOf())).copyOnDeath());

    private PlayerStores() {}

    /** Registers the attachment type (class initialisation); called while the blocks are registered. */
    public static void register() {
        LOGGER.debug("[{}] registered attachment {}", MOD_ID, TYPE.identifier());
    }

    /**
     * The store key of {@code block}: the id of the first stage of its weathering family (a waxed copy counts as its
     * source), so a chest that ages, is waxed, scraped or struck by lightning keeps showing the same store.
     */
    public static String key(Block block) {
        return BlockWaxing.familyRoot(BuiltInRegistries.BLOCK.getKey(block)).toString();
    }

    /** A copy of {@code player}'s store for {@code key}; empty when the player has none. */
    public static List<ItemStack> contents(Player player, String key) {
        return player.getAttachedOrElse(TYPE, Map.of()).getOrDefault(key, List.of()).stream().map(ItemStack::copy).toList();
    }

    /**
     * Opens {@code player}'s own store of the block at {@code storage} (server side); a locked block sends vanilla's
     * message and opens nothing.
     */
    static void open(StorageBlockEntity storage, Player player) {
        if (!storage.canOpen(player)) {
            return;
        }
        Store store = new Store(storage, player, key(storage.getBlockState().getBlock()));
        player.openMenu(new SimpleMenuProvider((id, inventory, p) -> ContainerMenus.create(storage.spec(), id, inventory, store),
                storage.getDisplayName()));
    }

    /** The store of one player seen through one block: loaded from the attachment, written back on every change and on close. */
    static final class Store extends SimpleContainer {
        private final StorageBlockEntity block;
        private final Player player;
        private final String key;

        Store(StorageBlockEntity block, Player player, String key) {
            super(block.spec().slotCount());
            this.block = block;
            this.player = player;
            this.key = key;
            List<ItemStack> saved = contents(player, key);
            for (int i = 0; i < saved.size() && i < getContainerSize(); i++) {
                super.setItem(i, saved.get(i));
            }
        }

        /** The block entity this store is seen through (its opener counter recognises the store's menu). */
        StorageBlockEntity block() {
            return block;
        }

        @Override
        public void setChanged() {
            super.setChanged();
            save();
        }

        @Override
        public boolean stillValid(Player viewer) {
            return viewer == player && !block.isRemoved() && Container.stillValidBlockEntity(block, viewer);
        }

        @Override
        public void startOpen(ContainerUser user) {
            block.startOpen(user);
        }

        @Override
        public void stopOpen(ContainerUser user) {
            save();
            block.stopOpen(user);
        }

        private void save() {
            Map<String, List<ItemStack>> all = new TreeMap<>(player.getAttachedOrElse(TYPE, Map.of()));
            List<ItemStack> items = new ArrayList<>(getContainerSize());
            for (int i = 0; i < getContainerSize(); i++) {
                items.add(getItem(i).copy());
            }
            all.put(key, List.copyOf(items));
            player.setAttached(TYPE, all);
        }
    }
}
